  'Có CLAUDE_CODE_OAUTH_TOKEN (token gói đăng ký) trong môi trường.': { en: 'CLAUDE_CODE_OAUTH_TOKEN (subscription token) is set in the environment.', zh: '环境中有 CLAUDE_CODE_OAUTH_TOKEN（订阅 token）。', ja: '環境に CLAUDE_CODE_OAUTH_TOKEN（サブスクの token）があります。', ko: '환경에 CLAUDE_CODE_OAUTH_TOKEN(구독 token)이 있습니다.', es: 'Hay CLAUDE_CODE_OAUTH_TOKEN (token de suscripción) en el entorno.', fr: 'CLAUDE_CODE_OAUTH_TOKEN (token d’abonnement) est défini dans l’environnement.', de: 'CLAUDE_CODE_OAUTH_TOKEN (Abo-Token) ist in der Umgebung gesetzt.', th: 'มี CLAUDE_CODE_OAUTH_TOKEN (token แพ็กเกจสมาชิก) ในสภาพแวดล้อม', id: 'Ada CLAUDE_CODE_OAUTH_TOKEN (token langganan) di lingkungan.' },
  'Model "{model}" chưa đúng dạng nhà-cung-cấp/model.': { en: 'Model "{model}" isn’t in provider/model format.', zh: '模型 "{model}" 不符合 提供商/模型 格式。', ja: 'モデル "{model}" が プロバイダー/モデル 形式になっていません。', ko: '모델 "{model}"이(가) 제공자/모델 형식이 아닙니다.', es: 'El modelo "{model}" no tiene el formato proveedor/modelo.', fr: 'Le modèle "{model}" n’est pas au format fournisseur/modèle.', de: 'Modell "{model}" hat nicht das Format Anbieter/Modell.', th: 'โมเดล "{model}" ไม่อยู่ในรูปแบบ ผู้ให้บริการ/โมเดล', id: 'Model "{model}" belum berformat penyedia/model.' },
  'Ví dụ: anthropic/claude-sonnet-5-5 hoặc openrouter/openai/gpt-5.': { en: 'For example: anthropic/claude-sonnet-5-5 or openrouter/openai/gpt-5.', zh: '例如：anthropic/claude-sonnet-5-5 或 openrouter/openai/gpt-5。', ja: '例: anthropic/claude-sonnet-5-5 または openrouter/openai/gpt-5。', ko: '예: anthropic/claude-sonnet-5-5 또는 openrouter/openai/gpt-5.', es: 'Por ejemplo: anthropic/claude-sonnet-5-5 u openrouter/openai/gpt-5.', fr: 'Par exemple : anthropic/claude-sonnet-5-5 ou openrouter/openai/gpt-5.', de: 'Beispiel: anthropic/claude-sonnet-5-5 oder openrouter/openai/gpt-5.', th: 'ตัวอย่าง: anthropic/claude-sonnet-5-5 หรือ openrouter/openai/gpt-5', id: 'Contoh: anthropic/claude-sonnet-5-5 atau openrouter/openai/gpt-5.' },
